String line = "";
bool overflow = false;
void executeLine() {
  bool valid = !overflow && line.startsWith("SET ") && line.length() >= 5 && line.length() <= 7;
  int value = 0;
  for (int i = 4; i < line.length(); i++) {
    char c = line.charAt(i);
    if (c < '0' || c > '9') valid = false;
    else value = value * 10 + (c - '0');
  }
  if (valid && value <= 255) {
    analogWrite(18, value);
    Serial.print("OK="); Serial.println(value);
  } else Serial.println("ERR");
  line = ""; overflow = false;
}
void setup() { Serial.begin(115200); pinMode(18, OUTPUT); analogWrite(18, 0); }
void loop() {
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\n') executeLine();
    else if (c != '\r' && !overflow) {
      if (line.length() < 12) line += c;
      else overflow = true;
    }
  }
}
